// Generate the offline resolver from Start's canonical, pure function body.
// Usage: node .github/sync-build-contract.mjs /path/to/Start/plugin/process-map/shared/buildState.ts
import { readFileSync, writeFileSync } from 'node:fs'
import { createHash } from 'node:crypto'
import { fileURLToPath } from 'node:url'
const source = process.argv[2]
if (!source || process.argv.length !== 3) throw Error('Provide the canonical buildState.ts file')
let code = readFileSync(source, 'utf8')
const body = code.match(/\/\/ BEGIN SHARED BUILD RESOLVER\n([\s\S]+?)\n  \/\/ END SHARED BUILD RESOLVER/)?.[1]
if (!body) throw Error('Canonical resolver markers are missing')
const fingerprint = createHash('sha256').update(body).digest('hex')
code = code.replace(/export const buildContractFingerprint = '[^']*'/, `export const buildContractFingerprint = '${fingerprint}'`)
writeFileSync(source, code)
writeFileSync(fileURLToPath(new URL('../scripts/lib/build-state.mjs', import.meta.url)),
  `// Generated by .github/sync-build-contract.mjs. Do not edit this resolver independently.\n` +
  `export const buildContractFingerprint = '${fingerprint}'\n` +
  `export function resolveBuildState(facts, common = []) {\n  // BEGIN SHARED BUILD RESOLVER\n${body}\n  // END SHARED BUILD RESOLVER\n}\n`)
